  "about.lead": "पारंपरिक ज्योतिषियों का",
  "about.accent": "परिवार",
  "about.rest": "",
  "about.body": "कुंडली, प्रश्न, मेल, पारिवारिक मार्गदर्शन और उपाय के लिए वीडियो परामर्श। पूजा और होम सावधानी से। पवित्र उत्पाद निजी पूछताछ पर। मंदिर यात्रा के लिए दर्शन नोट्स। ऑफ़लाइन पूजा उपलब्ध। सेवा विश्वव्यापी है।",
  "about.statYears": "500+ वर्ष",
  "about.statOnline": "ऑनलाइन विश्वव्यापी",
