  "about.read": "हमारी कहानी पढ़ें",
  "about.why": "ज्योतिष की आवश्यकता क्यों?",
  "about.whyCopy": "भविष्य बताने के लिए नहीं, बल्कि वर्तमान को स्पष्टता से समझने के लिए — और सही समय पर सही कर्म चुनने के लिए।",
  "about.why1Title": "दशा, दोष और पैटर्न की स्पष्टता",
  "about.why1Copy": "समझें कि वही संघर्ष क्यों दोहराता है — मंगल दोष, साढ़े साती, कालसर्प — और यह आपसे क्या सुधार माँग रहा है।",
  "about.why2Title": "सही निर्णयों के लिए सही समय",
  "about.why2Copy": "विवाह, गृह प्रवेश, व्यवसाय या यात्रा का मुहूर्त — ताकि आपका प्रयास समय के साथ हो, उसके विरुद्ध नहीं।",
  "about.why3Title": "उपाय जो संभव हों",
