  "faq.q3": "क्या ज्योतिषी अंकल के ज्योतिषी सत्यापित हैं?",
  "faq.a3": "हाँ। ज्योतिषी अंकल पर हर ज्योतिषी परामर्श से पहले सत्यापन प्रक्रिया से गुज़रता है।",
