  "faq.q5": "क्या मैं गुमनाम रूप से परामर्श ले सकता हूँ?",
  "faq.a5": "आप स्वतंत्र रूप से देख सकते हैं। सत्र के लिए बिना लॉगिन जारी रख सकते हैं, या अगली बार के लिए विवरण सहेजने हेतु पंजीकरण करें। हम आपकी जानकारी निजी रखते हैं।",
  "faq.q6": "भुगतान कैसे होता है?",
  "faq.a6": "सत्र का अनुरोध करने के बाद शुल्क निजी रूप से बताया जाता है। सार्वजनिक पृष्ठों पर रुपए की दरें नहीं हैं। भुगतान से पहले टीम से राशि की पुष्टि करें।",
