  "yatra.pace": "முதியோருக்கு ஏற்ற வேகம். ஒவ்வொரு மூல கோயிலிலும் நேரம்.",
  "yatra.private": "தனியார் குடும்ப யாத்திரை வேண்டுமா? பயணம், பூசாரி, தங்குமிடம் •",
  "yatra.circuits": "காசி • ராமேஸ்வரம் • சார்தாம் தனிச் சுற்றுகள்",
  "yatra.coordinator": "யாத்திரை ஒருங்கிணைப்பாளரிடம் பேசுங்கள்",
  "articles.kicker": "கற்க • வழிகாட்டிகள் • பரிகாரம் • கோயில் கதைகள்",
  "articles.lead": "நம்",
  "articles.accent": "கட்டுரைகள்",
  "articles.copy": "தோஷம், பரிகாரம், கோயில் கதைகள் மற்றும் தினசரி ஜோதிடத்தின் எளிய வழிகாட்டிகள். 3 நிமிடம் படித்து இன்றே பயன்படுத்துங்கள்.",
  "articles.copyEnd": "ஒவ்வொரு கட்டுரையும் பூஜை அல்லது ஆலோசனையுடன் இணைக்கப்பட்டுள்ளது.",
