  "articles.all": "அனைத்தும்",
  "articles.empty": "இந்த தலைப்பில் கட்டுரைகள் இல்லை. அனைத்தையும் முயல்க.",
  "articles.serviceNote": "சேவை முன் படிப்பு:",
  "articles.serviceNote2": "ஒவ்வொரு வழிகாட்டியும் இன்றே பதிவு செய்யக்கூடிய பூஜை அல்லது ஆலோசனையில் முடியும்.",
  "articles.youtube": "கட்டுரையை வீடியோவாக வேண்டுமா? மந்திரம் மற்றும் கோயில் காட்சிகளுடன் 3-நிமிட பரிகார ரீல்கள்.",
  "articles.watch": "YouTube-இல் பாருங்கள்",
  "articles.foot": "வழிகாட்டிகள் கற்க, அச்சத்திற்கு அல்ல. தனிப்பட்ட பரிகாரத்திற்கு கட்டுரையை பூஜை அல்லது வீடியோ ஆலோசனையுடன் இணைக்கவும்.",
