  "about.kicker": "எங்களைப் பற்றி",
  "about.lead": "பாரம்பரிய ஜோதிடர்களின்",
  "about.accent": "குடும்பம்",
  "about.rest": "",
  "about.body": "குண்டலி, பிரஷ்னா, பொருத்தம், குடும்ப வழிகாட்டல் மற்றும் பரிகாரங்களுக்கு வீடியோ ஆலோசனை. பூஜை மற்றும் ஹோமம் கவனத்துடன். புனித பொருட்கள் தனிப்பட்ட கேள்வி மூலம். கோயில் யாத்திரை தரிசன குறிப்புகள். ஆஃப்லைன் பூஜைகள் உண்டு. சேவை உலகளாவியது.",
  "about.statYears": "500+ ஆண்டுகள்",
  "about.statOnline": "ஆன்லைன் உலகளாவிய",
  "about.statOffline": "ஆஃப்லைன் பூஜைகள் உண்டு",
  "about.read": "எங்கள் கதையைப் படியுங்கள்",
  "about.why": "ஜோதிடம் ஏன் தேவை?",
  "about.whyCopy": "எதிர்காலத்தை சொல்ல அல்ல, தெளிவுடன் நிகழ்காலத்தை புரிந்துகொள்ள — சரியான நேரத்தில் சரியான கர்மத்தை தேர்ந்தெடுக்க.",
  "about.why1Title": "தசா, தோஷம் மற்றும் பாங்குகளின் தெளிவு",
  "about.why1Copy": "அதே போராட்டம் ஏன் மீண்டும் வருகிறது என்பதை புரிந்துகொள்ளுங்கள் — மங்கள தோஷம், சடே சதி, காலசர்ப்பம் — அது உங்களிடம் எதை சரிசெய்யக் கேட்கிறது.",
  "about.why2Title": "சரியான முடிவுகளுக்கு சரியான நேரம்",
  "about.why2Copy": "திருமணம், கிருகப்பிரவேசம், தொழில் அல்லது பயணத்திற்கான முகூர்த்தம் — உங்கள் முயற்சி காலத்துடன் இணைய, அதற்கு எதிராக அல்ல.",
  "about.why3Title": "செய்யக்கூடிய பரிகாரங்கள்",
  "about.why3Copy": "பயம் இல்லை, விலையுயர்ந்த ரத்தினங்கள் இல்லை. எளிய பூஜை, மந்திர ஜபம், தானம் மற்றும் ஒழுக்கமான பழக்கங்கள் — உங்கள் மொழியில்.",
  "about.guidance": "வழிகாட்டல், பயம் அல்ல",
  "about.trusted": "30+ நாடுகளில் உள்ள குடும்பங்களின் நம்பிக்கை",
