  "how.liveLine": "நேரடி • வீடியோ ஆலோசனை, உலகம் முழுவதும்",
  "how.response": "தனிப்பட்ட அமர்வுகள்",
  "how.vedic": "வேத • நம்பகமானது",
  "how.toast": "ஜோதிடரைத் தேடுகிறோம் — தேர்ந்தெடுக்கப்பட்ட வழிகாட்டிகள் திறக்கின்றன",
  "trust.copy": "பண்டைய ஞானத்தில் வேரூன்றி, நவீன கவனத்துடன். சரிபார்க்கப்பட்ட வழிகாட்டிகளின் வட்டம் உங்கள் பயணத்திற்கு.",
