  "enquiry.phQuery": "நீங்கள் எந்த தெளிவு அல்லது வழிகாட்டுதலை தேடுகிறீர்கள் என்பதை சுருக்கமாக எழுதுங்கள்...",
  "enquiry.faqTitle": "அடிக்கடி கேட்கப்படும் கேள்விகள்",
  "enquiry.faqCopy": "ஆலோசனை, ஜோதிடர்கள், வீடியோ மற்றும் கட்டணம் பற்றிய பதில்கள்.",
  "faq.q1": "ஜோதிட ஆலோசனை என்றால் என்ன?",
  "faq.a1": "ஜோதிஷி அங்கிள் ஜோதிடருடன் தனிப்பட்ட அமர்வு. உங்கள் கேள்வி மற்றும் பிறப்பு விவரங்களைப் பகிர்ந்து, குண்டலி, பிரஷ்னா, பொருத்தம், வேலை, குடும்பம், வாஸ்து அல்லது பரிகாரம் குறித்து வழிகாட்டல் பெறுவீர்கள் — அரட்டை, அழைப்பு அல்லது வீடியோவில்.",
  "faq.q2": "ஜோதிடரை எப்படி தேர்வு செய்வது?",
  "faq.a2": "இப்போது ஜோதிடரிடம் பேசுங்கள் திறக்கவும். அனைவரும், இப்போது ஆன்லைன், உயர் மதிப்பீடு அல்லது புதிய ஜோதிடர்கள், அல்லது ஒரு தலைப்பைத் தேர்வு செய்யுங்கள். சுயவிவரத்தைப் படித்து அரட்டை, அழைப்பு அல்லது வீடியோ தொடங்குங்கள்.",
  "faq.q3": "ஜோதிஷி அங்கிள் ஜோதிடர்கள் சரிபார்க்கப்பட்டவர்களா?",
  "faq.a3": "ஆம். ஜோதிஷி அங்கிளில் உள்ள ஒவ்வொரு ஜோதிடரும் ஆலோசனைக்கு முன் சரிபார்ப்பு செயல்முறைக்கு செல்கிறார்.",
  "faq.q4": "வீடியோ ஆலோசனை எப்படி வேலை செய்கிறது?",
  "faq.a4": "ஜோதிடரையும் நேரத்தையும் தேர்ந்தெடுத்து வீடியோ அமர்வைப் பதிவு செய்யுங்கள். உறுதிப்படுத்தலுக்குப் பிறகு சந்திப்பு இணைப்பு கிடைக்கும். வாசிப்பு நேரடி, நேருக்கு நேர், உங்கள் பிறப்பு விவரங்களை அடிப்படையாகக் கொண்டது.",
  "faq.q5": "நான் அநாமதேயமாக ஆலோசனை பெற முடியுமா?",
  "faq.a5": "நீங்கள் சுதந்திரமாக பார்க்கலாம். அமர்வுக்கு உள்நுழைவு இல்லாமல் தொடரலாம், அல்லது அடுத்த முறைக்காக விவரங்களைச் சேமிக்க பதிவு செய்யலாம். உங்கள் தகவலை நாங்கள் தனிப்பட்டதாக வைக்கிறோம்.",
  "faq.q6": "பணம் செலுத்துவது எப்படி?",
  "faq.a6": "அமர்வு கேட்ட பிறகு கட்டணம் தனிப்பட்ட முறையில் பகிரப்படும். பொது பக்கங்களில் ரூபாய் விலை இல்லை. செலுத்துவதற்கு முன் குழுவிடம் தொகையை உறுதி செய்யுங்கள்.",
  "faq.q7": "ஆலோசனையை ரத்து செய்ய முடியுமா?",
  "faq.a7": "ஆம். ரத்து செய்ய அல்லது நேரம் மாற்ற வாட்ஸ்அப்பில் குழுவிடம் எழுதுங்கள். ஜோதிடரின் நேரம் காலியாகும்படி முடிந்தவரை விரைவில் எழுதுங்கள்.",
  "faq.q8": "ஜோதிடராக எப்படி சேர்வது?",
  "faq.a8": "இந்த தளத்தில் ஜோதிடராக சேருங்கள் பயன்படுத்தி, பின்னர் ஜோதிடராக சேரவும். சுயவிவரம், அனுபவம், மொழிகள் மற்றும் சிறப்புகளை அனுப்புங்கள். குழு விண்ணப்பங்களைப் படிக்கும்.",
  "enquiry.unsure": "இன்னும் தயக்கம் உள்ளதா?",
  "enquiry.unsureCopy": "வாட்ஸ்அப்பில் எங்கள் குழுவிடம் பேசுங்கள். பணி நேரத்தில் பதிலளிக்கிறோம்.",
