  "about.body": "കുണ്ഡലി, പ്രശ്ന, പൊരുത്തം, കുടുംബ മാർഗനിർദേശം, പ്രതിവിധികൾക്ക് വീഡിയോ കൺസൾട്ടിങ്. പൂജയും ഹോമവും ശ്രദ്ധയോടെ. പുണ്യ ഉൽപ്പന്നങ്ങൾ സ്വകാര്യ ചോദ്യത്തിലൂടെ. ക്ഷേത്ര യാത്രക്ക് ദർശന കുറിപ്പുകൾ. ഓഫ്‌ലൈൻ പൂജകൾ ലഭ്യം. സേവനം ലോകവ്യാപകം.",
