  "about.why": "ജ്യോതിഷം എന്തിന്?",
  "about.whyCopy": "ഭാവി പ്രവചിക്കാനല്ല, വർത്തമാനം വ്യക്തമായി മനസ്സിലാക്കാനും ശരിയായ സമയത്ത് ശരിയായ കർമ്മം തിരഞ്ഞെടുക്കാനും.",
  "about.why1Title": "ദശ, ദോഷം, ആവർത്തനങ്ങളുടെ വ്യക്തത",
  "about.why1Copy": "അതേ പോരാട്ടം എന്തുകൊണ്ട് ആവർത്തിക്കുന്നു എന്ന് മനസ്സിലാക്കുക — മംഗളദോഷം, സഡേ സതി, കാലസർപ്പം — അത് നിങ്ങളോട് എന്ത് തിരുത്താൻ ആവശ്യപ്പെടുന്നു.",
  "about.why2Title": "ശരിയായ തീരുമാനങ്ങൾക്ക് ശരിയായ സമയം",
  "about.why2Copy": "വിവാഹം, ഗൃഹപ്രവേശം, ബിസിനസ്, യാത്ര എന്നിവയ്ക്കുള്ള മുഹൂർത്തം — നിങ്ങളുടെ ശ്രമം കാലത്തോടൊപ്പം ചേരാൻ, അതിനെതിരെ അല്ല.",
  "about.why3Title": "ചെയ്യാവുന്ന പ്രതിവിധികൾ",
  "about.why3Copy": "ഭയമില്ല, വിലയേറിയ രത്നങ്ങളില്ല. ലളിതമായ പൂജ, മന്ത്രജപം, ദാനം, അച്ചടക്കമുള്ള ശീലങ്ങൾ — നിങ്ങളുടെ ഭാഷയിൽ.",
