  "enquiry.copy": "പൂജ, കൺസൾട്ടേഷൻ, ഉൽപ്പന്നം അല്ലെങ്കിൽ യാത്ര — ഒരു ചെറിയ കുറിപ്പ് മതി. ഞങ്ങൾ ഇത് ടീമിനായി സൂക്ഷിക്കുന്നു.",
