  "enquiry.faqTitle": "പതിവായി ചോദിക്കുന്ന ചോദ്യങ്ങൾ",
  "enquiry.faqCopy": "കൺസൾട്ടേഷൻ, ജ്യോതിഷികൾ, വീഡിയോ, പേയ്‌മെന്റ് എന്നിവയെക്കുറിച്ചുള്ള ഉത്തരങ്ങൾ.",
  "faq.q1": "ജ്യോതിഷ കൺസൾട്ടേഷൻ എന്താണ്?",
  "faq.a1": "ജ്യോതിഷി അങ്കിളിലെ ജ്യോതിഷിയുമായുള്ള വ്യക്തിഗത സെഷൻ. നിങ്ങളുടെ ചോദ്യവും ജനന വിവരങ്ങളും പങ്കുവെച്ച്, കുണ്ഡലി, പ്രശ്ന, പൊരുത്തം, കരിയർ, കുടുംബം, വാസ്തു അല്ലെങ്കിൽ പ്രതിവിധി എന്നിവയിൽ മാർഗനിർദേശം ലഭിക്കും — ചാറ്റ്, കോൾ, വീഡിയോ.",
  "faq.q2": "ജ്യോതിഷിയെ എങ്ങനെ തിരഞ്ഞെടുക്കാം?",
  "faq.a2": "ഇപ്പോൾ ഒരു ജ്യോതിഷിയുമായി സംസാരിക്കുക തുറക്കുക. എല്ലാവരും, ഇപ്പോൾ ഓൺലൈൻ, ടോപ്പ് റേറ്റഡ് അല്ലെങ്കിൽ പുതിയ ജ്യോതിഷികൾ, അല്ലെങ്കിൽ ഒരു വിഷയം തിരഞ്ഞെടുക്കുക. പ്രൊഫൈൽ വായിച്ച് ചാറ്റ്, കോൾ അല്ലെങ്കിൽ വീഡിയോ ആരംഭിക്കുക.",
  "faq.q3": "ജ്യോതിഷി അങ്കിൾ ജ്യോതിഷികൾ സ്ഥിരീകരിച്ചവരാണോ?",
  "faq.a3": "അതെ. ജ്യോതിഷി അങ്കിളിലെ ഓരോ ജ്യോതിഷിയും കൺസൾട്ട് ചെയ്യുന്നതിന് മുമ്പ് സ്ഥിരീകരണ പ്രക്രിയയിലൂടെ കടന്നുപോകുന്നു.",
  "faq.q4": "വീഡിയോ കൺസൾട്ടേഷൻ എങ്ങനെ പ്രവർത്തിക്കുന്നു?",
  "faq.a4": "ജ്യോതിഷിയെയും സമയവും തിരഞ്ഞെടുത്ത് വീഡിയോ സെഷൻ ബുക്ക് ചെയ്യുക. സ്ഥിരീകരണത്തിന് ശേഷം മീറ്റിങ് ലിങ്ക് ലഭിക്കും. വായന ലൈവ്, മുഖാമുഖം, നിങ്ങളുടെ ജനന വിവരങ്ങളെ അടിസ്ഥാനമാക്കിയുള്ളതാണ്.",
  "faq.q5": "ഞാൻ അജ്ഞാതമായി കൺസൾട്ട് ചെയ്യാമോ?",
  "faq.a5": "നിങ്ങൾക്ക് സ്വതന്ത്രമായി കാണാം. സെഷന് ലോഗിൻ ഇല്ലാതെ തുടരാം, അല്ലെങ്കിൽ അടുത്ത തവണയ്ക്ക് വിവരങ്ങൾ സൂക്ഷിക്കാൻ രജിസ്റ്റർ ചെയ്യാം. നിങ്ങളുടെ വിവരങ്ങൾ ഞങ്ങൾ സ്വകാര്യമായി സൂക്ഷിക്കുന്നു.",
  "faq.q6": "പേയ്‌മെന്റ് എങ്ങനെയാണ്?",
  "faq.a6": "സെഷൻ അഭ്യർത്ഥിച്ച ശേഷം ഫീസ് സ്വകാര്യമായി പങ്കുവെക്കും. പൊതു പേജുകളിൽ രൂപ നിരക്കുകൾ ഇല്ല. അടയ്ക്കുന്നതിന് മുമ്പ് ടീമിനോട് തുക സ്ഥിരീകരിക്കുക.",
  "faq.q7": "കൺസൾട്ടേഷൻ റദ്ദാക്കാമോ?",
  "faq.a7": "അതെ. റദ്ദാക്കാനോ സമയം മാറ്റാനോ വാട്ട്‌സ്ആപ്പിൽ ടീമിന് എഴുതുക. ജ്യോതിഷിയുടെ സമയം ഒഴിവാകാനായി കഴിയുന്നത്ര നേരത്തെ എഴുതുക.",
  "faq.q8": "ജ്യോതിഷിയാകാൻ എങ്ങനെ?",
  "faq.a8": "ഈ സൈറ്റിൽ ജ്യോതിഷിയാകുക ഉപയോഗിച്ച്, പിന്നെ ജ്യോതിഷിയായി ചേരുക. പ്രൊഫൈൽ, അനുഭവം, ഭാഷകൾ, സ്പെഷ്യാലിറ്റികൾ സമർപ്പിക്കുക. ടീം അപേക്ഷകൾ വായിക്കും.",
  "enquiry.unsure": "ഇപ്പോഴും സംശയമുണ്ടോ?",
