  "about.accent": "ಕುಟುಂಬ",
  "about.rest": "",
  "about.body": "ಕುಂಡಲಿ, ಪ್ರಶ್ನೆ, ಹೊಂದಾಣಿಕೆ, ಕುಟುಂಬ ಮಾರ್ಗದರ್ಶನ ಮತ್ತು ಪರಿಹಾರಗಳಿಗೆ ವೀಡಿಯೊ ಸಮಾಲೋಚನೆ. ಪೂಜೆ ಮತ್ತು ಹೋಮ ಎಚ್ಚರಿಕೆಯಿಂದ. ಪವಿತ್ರ ಉತ್ಪನ್ನಗಳು ಖಾಸಗಿ ವಿಚಾರಣೆಯಲ್ಲಿ. ದೇವಾಲಯ ಯಾತ್ರೆಗೆ ದರ್ಶನ ಟಿಪ್ಪಣಿಗಳು. ಆಫ್‌ಲೈನ್ ಪೂಜೆಗಳು ಲಭ್ಯ. ಸೇವೆ ವಿಶ್ವವ್ಯಾಪಿ.",
  "about.statYears": "500+ ವರ್ಷಗಳು",
  "about.statOnline": "ಆನ್‌ಲೈನ್ ವಿಶ್ವವ್ಯಾಪಿ",
