  "about.why": "ಜ್ಯೋತಿಷ್ಯ ಏಕೆ ಬೇಕು?",
  "about.whyCopy": "ಭವಿಷ್ಯ ಹೇಳಲು ಅಲ್ಲ, ವರ್ತಮಾನವನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು — ಸರಿಯಾದ ಸಮಯದಲ್ಲಿ ಸರಿಯಾದ ಕರ್ಮವನ್ನು ಆಯ್ಕೆ ಮಾಡಲು.",
  "about.why1Title": "ದಶಾ, ದೋಷ ಮತ್ತು ಮಾದರಿಗಳ ಸ್ಪಷ್ಟತೆ",
  "about.why1Copy": "ಅದೇ ಹೋರಾಟ ಏಕೆ ಪುನರಾವರ್ತನೆಯಾಗುತ್ತದೆ ಎಂದು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಿ — ಮಂಗಳ ದೋಷ, ಸಡೆ ಸತಿ, ಕಾಲಸರ್ಪ — ಅದು ನಿಮ್ಮಿಂದ ಏನು ಸರಿಪಡಿಸಲು ಕೇಳುತ್ತಿದೆ.",
  "about.why2Title": "ಸರಿಯಾದ ನಿರ್ಧಾರಗಳಿಗೆ ಸರಿಯಾದ ಸಮಯ",
  "about.why2Copy": "ವಿವಾಹ, ಗೃಹಪ್ರವೇಶ, ವ್ಯಾಪಾರ ಅಥವಾ ಪ್ರಯಾಣದ ಮುಹೂರ್ತ — ನಿಮ್ಮ ಪ್ರಯತ್ನ ಕಾಲದೊಂದಿಗೆ ಹೊಂದಿಕೆಯಾಗಲು, ಅದಕ್ಕೆ ವಿರುದ್ಧವಾಗಿ ಅಲ್ಲ.",
  "about.why3Title": "ಮಾಡಬಹುದಾದ ಪರಿಹಾರಗಳು",
  "about.why3Copy": "ಭಯವಿಲ್ಲ, ದುಬಾರಿ ರತ್ನಗಳಿಲ್ಲ. ಸರಳ ಪೂಜೆ, ಮಂತ್ರ ಜಪ, ದಾನ ಮತ್ತು ಶಿಸ್ತಿನ ಅಭ್ಯಾಸಗಳು — ನಿಮ್ಮ ಭಾಷೆಯಲ್ಲಿ.",
