  "how.toast": "ಜ್ಯೋತಿಷಿಯನ್ನು ಹುಡುಕಲಾಗುತ್ತಿದೆ — ಆಯ್ದ ಮಾರ್ಗದರ್ಶಕರು ತೆರೆಯುತ್ತಾರೆ",
  "trust.copy": "ಪ್ರಾಚೀನ ಜ್ಞಾನದಲ್ಲಿ ಬೇರೂರಿ, ಆಧುನಿಕ ಕಾಳಜಿಯೊಂದಿಗೆ. ಪರಿಶೀಲಿತ ಮಾರ್ಗದರ್ಶಕರ ವಲಯ ನಿಮ್ಮ ಪ್ರಯಾಣಕ್ಕೆ.",
  "pop.expand": "ವೈದಿಕ ತತ್ವಗಳಲ್ಲಿ ನೆಲೆಗೊಂಡ ವೈಯಕ್ತಿಕ ಮಾರ್ಗದರ್ಶನ. ಪರಿಶೀಲಿತ ಜ್ಯೋತಿಷಿಯೊಂದಿಗೆ ಈ ವಿಷಯ ತೆರೆಯಿರಿ.",
