  "join.copy": "ನಿಮ್ಮ ಪರಿಣತಿಯನ್ನು ಅರ್ಥಪೂರ್ಣ ಸಮಾಲೋಚನೆಯಾಗಿ ಮಾಡಿ ಮತ್ತು JyothishiUncle ಜೊತೆ ಅಭ್ಯಾಸವನ್ನು ಬೆಳೆಸಿ.",
  "join.item1": "ನಿಮ್ಮ ವೃತ್ತಿಪರ ಪ್ರೊಫೈಲ್ ನಿರ್ಮಿಸಿ",
  "join.item2": "ಹೊಸ ಗ್ರಾಹಕರೊಂದಿಗೆ ಸಂಪರ್ಕಿಸಿ",
