  "join.login": "ಈಗಾಗಲೇ ನೋಂದಾಯಿಸಿದ್ದೀರಾ? ಲಾಗಿನ್",
  "enquiry.kicker": "ಪವಿತ್ರ ವಿಚಾರಣೆಗಳು",
  "enquiry.lead": "ಒಂದು ಪವಿತ್ರ",
  "enquiry.accent": "ವಿಚಾರಣೆ ಕಳುಹಿಸಿ",
  "enquiry.copy": "ಪೂಜೆ, ಸಮಾಲೋಚನೆ, ಉತ್ಪನ್ನ ಅಥವಾ ಯಾತ್ರೆ — ಒಂದು ಚಿಕ್ಕ ಟಿಪ್ಪಣಿ ಸಾಕು. ನಾವು ಇದನ್ನು ತಂಡಕ್ಕಾಗಿ ಉಳಿಸುತ್ತೇವೆ.",
  "enquiry.name": "ನಿಮ್ಮ ಹೆಸರು",
  "enquiry.mobile": "ಮೊಬೈಲ್ / ವಾಟ್ಸಾಪ್",
  "enquiry.email": "ಇಮೇಲ್",
  "enquiry.location": "ಸ್ಥಳ / ದೇಶ",
  "enquiry.subject": "ವಿಷಯ",
  "enquiry.hear": "ಜ್ಯೋತಿಷಿ ಅಂಕಲ್ ಬಗ್ಗೆ ಹೇಗೆ ತಿಳಿದಿರಿ?",
  "enquiry.query": "ನಿಮ್ಮ ಪ್ರಶ್ನೆ / ಆಧ್ಯಾತ್ಮಿಕ ಸಂದೇಶ",
  "enquiry.private": "ಇದು ನಿಮ್ಮ ಸಂಕಲ್ಪಕ್ಕೆ ಖಾಸಗಿ.",
