  "enquiry.sending": "ಕಳುಹಿಸಲಾಗುತ್ತಿದೆ…",
  "enquiry.legal": "ಕಳುಹಿಸುವುದರಿಂದ ಈ ವಿಚಾರಣೆಗೆ ವಾಟ್ಸಾಪ್ ಅಥವಾ ಇಮೇಲ್ ಮೂಲಕ ಸಂಪರ್ಕಕ್ಕೆ ನೀವು ಒಪ್ಪುತ್ತೀರಿ.",
  "enquiry.toast": "ವಿಚಾರಣೆ ಕಳುಹಿಸಲಾಗಿದೆ — ತಂಡ ವಾಟ್ಸಾಪ್‌ನಲ್ಲಿ ಉತ್ತರಿಸುತ್ತದೆ",
  "enquiry.toastSub": "ತಂಡಕ್ಕಾಗಿ ಉಳಿಸಲಾಗಿದೆ",
  "enquiry.error": "ಕಳುಹಿಸಲಾಗಲಿಲ್ಲ.",
  "enquiry.phName": "ನಿಮ್ಮ ಹೆಸರು",
  "enquiry.phMobile": "+91 …",
  "enquiry.phEmail": "you@email.com",
  "enquiry.phLocation": "ನಗರ, ದೇಶ",
  "enquiry.phQuery": "ನೀವು ಹುಡುಕುತ್ತಿರುವ ಸ್ಪಷ್ಟತೆ ಅಥವಾ ಮಾರ್ಗದರ್ಶನವನ್ನು ಸಂಕ್ಷಿಪ್ತವಾಗಿ ಬರೆಯಿರಿ...",
  "enquiry.faqTitle": "ಪದೇ ಪದೇ ಕೇಳುವ ಪ್ರಶ್ನೆಗಳು",
  "enquiry.faqCopy": "ಸಮಾಲೋಚನೆ, ಜ್ಯೋತಿಷಿಗಳು, ವೀಡಿಯೊ ಮತ್ತು ಪಾವತಿಯ ಉತ್ತರಗಳು.",
  "faq.q1": "ಜ್ಯೋತಿಷ ಸಮಾಲೋಚನೆ ಎಂದರೇನು?",
  "faq.a1": "ಜ್ಯೋತಿಷಿ ಅಂಕಲ್ ಜ್ಯೋತಿಷಿಯೊಂದಿಗೆ ವೈಯಕ್ತಿಕ ಅಧಿವೇಶನ. ನಿಮ್ಮ ಪ್ರಶ್ನೆ ಮತ್ತು ಜನ್ಮ ವಿವರಗಳನ್ನು ಹಂಚಿಕೊಂಡು, ಕುಂಡಲಿ, ಪ್ರಶ್ನೆ, ಹೊಂದಾಣಿಕೆ, ವೃತ್ತಿ, ಕುಟುಂಬ, ವಾಸ್ತು ಅಥವಾ ಪರಿಹಾರಗಳ ಮಾರ್ಗದರ್ಶನ ಪಡೆಯಿರಿ — ಚಾಟ್, ಕರೆ ಅಥವಾ ವೀಡಿಯೊದಲ್ಲಿ.",
  "faq.q2": "ಜ್ಯೋತಿಷಿಯನ್ನು ಹೇಗೆ ಆಯ್ಕೆ ಮಾಡುವುದು?",
  "faq.a2": "ಈಗ ಜ್ಯೋತಿಷಿಯೊಂದಿಗೆ ಮಾತನಾಡಿ ತೆರೆಯಿರಿ. ಎಲ್ಲಾ, ಈಗ ಆನ್‌ಲೈನ್, ಟಾಪ್ ರೇಟೆಡ್ ಅಥವಾ ಹೊಸ ಜ್ಯೋತಿಷಿಗಳು, ಅಥವಾ ವಿಷಯವನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಪ್ರೊಫೈಲ್ ಓದಿ, ನಂತರ ಚಾಟ್, ಕರೆ ಅಥವಾ ವೀಡಿಯೊ ಪ್ರಾರಂಭಿಸಿ.",
  "faq.q3": "ಜ್ಯೋತಿಷಿ ಅಂಕಲ್ ಜ್ಯೋತಿಷಿಗಳು ಪರಿಶೀಲಿತರೇ?",
  "faq.a3": "ಹೌದು. ಜ್ಯೋತಿಷಿ ಅಂಕಲ್‌ನಲ್ಲಿ ಪ್ರತಿ ಜ್ಯೋತಿಷಿ ಸಮಾಲೋಚನೆ ಮಾಡುವ ಮೊದಲು ಪರಿಶೀಲನೆ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಹಾದುಹೋಗುತ್ತಾರೆ.",
  "faq.q4": "ವೀಡಿಯೊ ಸಮಾಲೋಚನೆ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?",
  "faq.a4": "ಜ್ಯೋತಿಷಿ ಮತ್ತು ಸಮಯವನ್ನು ಆಯ್ಕೆಮಾಡಿ, ನಂತರ ವೀಡಿಯೊ ಅಧಿವೇಶನ ಬುಕ್ ಮಾಡಿ. ದೃಢೀಕರಣದ ನಂತರ ಸಭೆಯ ಲಿಂಕ್ ಸಿಗುತ್ತದೆ. ಓದುವಿಕೆ ಲೈವ್, ಮುಖಾಮುಖಿ ಮತ್ತು ನಿಮ್ಮ ಜನ್ಮ ವಿವರಗಳನ್ನು ಆಧರಿಸಿದೆ.",
  "faq.q5": "ನಾನು ಅನಾಮಧೇಯವಾಗಿ ಸಮಾಲೋಚಿಸಬಹುದೇ?",
  "faq.a5": "ನೀವು ಸ್ವತಂತ್ರವಾಗಿ ನೋಡಬಹುದು. ಅಧಿವೇಶನಕ್ಕೆ ಲಾಗಿನ್ ಇಲ್ಲದೆ ಮುಂದುವರಿಯಬಹುದು, ಅಥವಾ ಮುಂದಿನ ಬಾರಿಗೆ ವಿವರಗಳನ್ನು ಉಳಿಸಲು ನೋಂದಾಯಿಸಿ. ನಿಮ್ಮ ಮಾಹಿತಿಯನ್ನು ನಾವು ಖಾಸಗಿಯಾಗಿ ಇಡುತ್ತೇವೆ.",
  "faq.q6": "ಪಾವತಿ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?",
  "faq.a6": "ಅಧಿವೇಶನ ಕೇಳಿದ ನಂತರ ಶುಲ್ಕವನ್ನು ಖಾಸಗಿಯಾಗಿ ಹಂಚಲಾಗುತ್ತದೆ. ಸಾರ್ವಜನಿಕ ಪುಟಗಳಲ್ಲಿ ರೂಪಾಯಿ ದರಗಳಿಲ್ಲ. ಪಾವತಿಸುವ ಮೊದಲು ತಂಡದೊಂದಿಗೆ ಮೊತ್ತವನ್ನು ದೃಢೀಕರಿಸಿ.",
  "faq.q7": "ಸಮಾಲೋಚನೆಯನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದೇ?",
  "faq.a7": "ಹೌದು. ರದ್ದುಗೊಳಿಸಲು ಅಥವಾ ಸಮಯ ಬದಲಾಯಿಸಲು ವಾಟ್ಸ್‌ಆಪ್‌ನಲ್ಲಿ ತಂಡಕ್ಕೆ ಬರೆಯಿರಿ. ಜ್ಯೋತಿಷಿಯ ಸಮಯ ಖಾಲಿಯಾಗುವಂತೆ ಸಾಧ್ಯವಾದಷ್ಟು ಬೇಗ ಬರೆಯಿರಿ.",
  "faq.q8": "ಜ್ಯೋತಿಷಿಯಾಗಿ ಹೇಗೆ ಸೇರುವುದು?",
  "faq.a8": "ಈ ಸೈಟ್‌ನಲ್ಲಿ ಜ್ಯೋತಿಷಿಯಾಗಿ ಬಳಸಿ, ನಂತರ ಜ್ಯೋತಿಷಿಯಾಗಿ ಸೇರಿ. ಪ್ರೊಫೈಲ್, ಅನುಭವ, ಭಾಷೆಗಳು ಮತ್ತು ವಿಶೇಷತೆಗಳನ್ನು ಸಲ್ಲಿಸಿ. ತಂಡವು ಅರ್ಜಿಗಳನ್ನು ಓದುತ್ತದೆ.",
  "enquiry.unsure": "ಇನ್ನೂ ಸಂದೇಹವಿದೆಯೇ?",
  "enquiry.unsureCopy": "ವಾಟ್ಸಾಪ್‌ನಲ್ಲಿ ನಮ್ಮ ತಂಡದೊಂದಿಗೆ ಮಾತನಾಡಿ. ಕೆಲಸದ ವೇಳೆಯಲ್ಲಿ ಉತ್ತರಿಸುತ್ತೇವೆ.",
  "enquiry.chat": "ವಾಟ್ಸಾಪ್‌ನಲ್ಲಿ ಚಾಟ್",
