  "about.why": "జ్యోతిష్యం ఎందుకు?",
  "about.whyCopy": "భవిష్యత్తు చెప్పడానికి కాదు, వర్తమానాన్ని స్పష్టంగా అర్థం చేసుకోవడానికి — సరైన సమయంలో సరైన కర్మను ఎంచుకోవడానికి.",
  "about.why1Title": "దశ, దోషం మరియు నమూనాల స్పష్టత",
  "about.why1Copy": "అదే పోరాటం ఎందుకు పునరావృతమవుతుందో అర్థం చేసుకోండి — మంగళ దోషం, సడే సతి, కాలసర్పం — అది మీ నుండి ఏమి సరిచేయమని అడుగుతోంది.",
  "about.why2Title": "సరైన నిర్ణయాలకు సరైన సమయం",
  "about.why2Copy": "వివాహం, గృహప్రవేశం, వ్యాపారం లేదా ప్రయాణానికి ముహూర్తం — మీ ప్రయత్నం కాలంతో కలిసి ఉండేలా, దానికి వ్యతిరేకంగా కాదు.",
  "about.why3Title": "చేయగలిగే పరిష్కారాలు",
  "about.why3Copy": "భయం లేదు, ఖరీదైన రత్నాలు లేవు. సరళమైన పూజ, మంత్ర జపం, దానం మరియు క్రమశిక్షణ అలవాట్లు — మీ భాషలో.",
  "about.guidance": "మార్గదర్శకం, భయం కాదు",
  "about.trusted": "30+ దేశాల కుటుంబాల నమ్మకం",
