  "trust.copy": "ప్రాచీన జ్ఞానంలో వేరుతో, ఆధునిక శ్రద్ధతో. ధృవీకరించిన మార్గదర్శకుల వలయం మీ ప్రయాణానికి.",
  "pop.expand": "వైదిక సూత్రాలపై ఆధారపడిన వ్యక్తిగత మార్గదర్శకం. ధృవీకరించిన జ్యోతిష్కునితో ఈ అంశం తెరవండి.",
