  "join.copy": "మీ నైపుణ్యాన్ని అర్థవంతమైన సంప్రదింపుగా మార్చి JyothishiUncleతో మీ అభ్యాసాన్ని పెంచుకోండి.",
  "join.item1": "మీ ప్రొఫెషనల్ ప్రొఫైల్ నిర్మించండి",
  "join.item2": "కొత్త క్లయింట్లతో కనెక్ట్ అవ్వండి",
