  "enquiry.kicker": "పవిత్ర విచారణలు",
  "enquiry.lead": "ఒక పవిత్ర",
  "enquiry.accent": "విచారణ పంపండి",
  "enquiry.copy": "పూజ, సంప్రదింపు, ఉత్పత్తి లేదా యాత్ర — ఒక చిన్న గమనిక సరిపోతుంది. మేము దీన్ని బృందం కోసం భద్రపరుస్తాము.",
