  "enquiry.phMobile": "+91 …",
  "enquiry.phEmail": "you@email.com",
  "enquiry.phLocation": "నగరం, దేశం",
  "enquiry.phQuery": "మీరు వెతుకుతున్న స్పష్టత లేదా మార్గదర్శకతను క్లుప్తంగా రాయండి...",
  "enquiry.faqTitle": "తరచుగా అడిగే ప్రశ్నలు",
  "enquiry.faqCopy": "సంప్రదింపులు, జ్యోతిష్కులు, వీడియో మరియు చెల్లింపు గురించిన సమాధానాలు.",
  "faq.q1": "జ్యోతిష్య సంప్రదింపు అంటే ఏమిటి?",
  "faq.a1": "జ్యోతిషి అంకుల్ జ్యోతిష్కునితో వ్యక్తిగత సెషన్. మీ ప్రశ్న మరియు జన్మ వివరాలను పంచుకుని, కుండలి, ప్రశ్న, సరిపోలిక, వృత్తి, కుటుంబం, వాస్తు లేదా పరిష్కారాలపై మార్గదర్శకం పొందండి — చాట్, కాల్ లేదా వీడియోలో.",
  "faq.q2": "జ్యోతిష్కుడిని ఎలా ఎంచుకోవాలి?",
  "faq.a2": "ఇప్పుడు జ్యోతిష్కునితో మాట్లాడండి తెరవండి. అన్నీ, ఇప్పుడు ఆన్‌లైన్, టాప్ రేటెడ్ లేదా కొత్త జ్యోతిష్కులు, లేదా ఒక అంశం ఎంచుకోండి. ప్రొఫైల్ చదివి చాట్, కాల్ లేదా వీడియో ప్రారంభించండి.",
  "faq.q3": "జ్యోతిషి అంకుల్ జ్యోతిష్కులు ధృవీకరించబడినవారా?",
  "faq.a3": "అవును. జ్యోతిషి అంకుల్‌లో ప్రతి జ్యోతిష్కుడు సంప్రదింపుకు ముందు ధృవీకరణ ప్రక్రియను దాటుతారు.",
  "faq.q4": "వీడియో సంప్రదింపు ఎలా పనిచేస్తుంది?",
  "faq.a4": "జ్యోతిష్కుడిని మరియు సమయాన్ని ఎంచుకుని వీడియో సెషన్ బుక్ చేయండి. నిర్ధారణ తర్వాత మీటింగ్ లింక్ వస్తుంది. పఠనం లైవ్, ముఖాముఖి మరియు మీ జన్మ వివరాలపై ఆధారపడి ఉంటుంది.",
  "faq.q5": "నేను అనామకంగా సంప్రదించవచ్చా?",
  "faq.a5": "మీరు స్వేచ్ఛగా చూడవచ్చు. సెషన్ కోసం లాగిన్ లేకుండా కొనసాగవచ్చు, లేదా తదుపరి సారి వివరాలు సేవ్ చేయడానికి నమోదు చేసుకోండి. మీ సమాచారాన్ని మేము ప్రైవేట్‌గా ఉంచుతాము.",
  "faq.q6": "చెల్లింపు ఎలా పనిచేస్తుంది?",
  "faq.a6": "సెషన్ అభ్యర్థించిన తర్వాత రుసుము ప్రైవేట్‌గా పంచుకుంటారు. పబ్లిక్ పేజీల్లో రూపాయి రేట్లు లేవు. చెల్లించే ముందు బృందంతో మొత్తాన్ని నిర్ధారించండి.",
